import java.io.*;
import java.util.*;

public class Codeforces
{
    public static void main(String[] args) throws Exception
    {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int totalNumbers = Integer.parseInt(parts[0]);
        double targetProbability = Double.parseDouble(parts[1]);
        int resultIndex;
        for(resultIndex=0; resultIndex<=totalNumbers; resultIndex++)
        {
            if(computeProbability(totalNumbers, resultIndex) >= targetProbability) break;
        }
        System.out.println(resultIndex);
        br.close();
    }

    static int ncr(int n, int r)
    {
        if(r > n) return 0;
        int val=1;
        for(int i=n; i>n-r; i--) val*=i;
        for(int i=2; i<=r; i++) val/=i;
        return val;
    }

    static double computeProbability(int n, int x)
    {
        int a = ncr(x, 3) * ncr(n - x, 0);
        int b = ncr(x, 2) * ncr(n - x, 1);
        int c = ncr(x, 1) * ncr(n - x, 2);
        return ((3.0/6)*c + a + b) / ncr(n, 3);
    }
}
